questionvariables.text:
/* Randomise (PA, AB); PB = PA + AB. PT = sqrt(PA*PB) is a whole number exactly
   when PA*PB is a perfect square, selected by integerp(sqrt(PA*PB)). */
data : sublist(
  create_list([pa,ab], pa,2,14, ab,2,26),
  lambda([z], is(
        integerp(sqrt(z[1]*(z[1]+z[2])))
    and sqrt(z[1]*(z[1]+z[2])) >= 4 and sqrt(z[1]*(z[1]+z[2])) <= 18
    and z[1]+z[2] <= 32 )));
sel : rand(data);
PA : sel[1];
AB : sel[2];
PB : PA + AB;
ta_pt : sqrt(PA*PB);            /* tangent length PT */
wrong_nosqrt : PA*PB;           /* gave PT^2 = PA*PB (forgot the square root) */
wrong_useAB_sqrt : sqrt(PA*AB); /* used chord AB instead of PB (square root taken) */
wrong_useAB_raw : PA*AB;        /* used AB and forgot the square root */
